'use strict';
// Navigation, project lifecycle and layout use the same document identities.
let recentProjects=[],openingProject=false,launcherError='';
const projectImages=new Map();
function clearProjectImages(){for(const item of projectImages.values())if(item.url?.startsWith('blob:'))URL.revokeObjectURL(item.url);projectImages.clear()}
async function loadRecentProjects(){const result=await window.projectAdapter.recent?.();if(result?.error){launcherError=result.error;return}recentProjects=result?.projects||[]}
function recentProjectRows(){return recentProjects.map(p=>`<div class="recent-project-row"><button data-recent-project="${esc(p.id)}">${icon('folder-open')}<span><strong>${esc(p.name)}</strong><small>${esc(p.path)}</small><time>${p.lastOpened?formatDate(p.lastOpened):''}${p.sessionOnly?' · nesta sessão':''}</time></span>${icon('arrow')}</button><button class="icon-button" data-forget-project="${esc(p.id)}" title="Remover dos recentes, mantendo os arquivos" aria-label="Remover ${esc(p.name)} dos recentes">${icon('close')}</button></div>`).join('')||'<div class="recent-project-empty">Suas pastas aparecerão aqui depois de abertas.<br>Os arquivos continuam no local original.</div>'}
function showLauncher(){modal('Seu próximo espaço',`<div class="launcher-layout"><section class="launcher-intro"><div class="launcher-mark"><img src="assets/amago-mark.svg" alt=""></div><div class="eyebrow">ÂMAGO / 2.5</div><h1>Onde suas ideias<br>se encontram.</h1><p>Retome um projeto ou encontre espaço para um novo pensamento.</p><button class="solid-button" data-launch-vault>${icon('core')}Meu universo<span>Espaço pessoal</span></button><button class="plain-button" data-workspace-action="open">${icon('folder-open')}Abrir pasta</button>${workbench.project?'<button class="plain-button" data-workspace-action="project">Voltar ao projeto aberto</button>':''}</section><section class="launcher-recents"><div class="eyebrow">CONTINUE DE ONDE PAROU</div><h2>Projetos recentes <small>${recentProjects.length}</small></h2><label class="side-search">${icon('search')}<input id="recent-project-query" placeholder="Encontrar um projeto…" aria-label="Buscar projetos recentes"></label><p class="launcher-error" role="status">${esc(launcherError)}</p><div id="recent-project-list">${recentProjectRows()}</div><p class="launcher-foot">${window.amagoDesktop?'Pastas locais, reabertas em um clique.':'O navegador pode solicitar novamente a permissão para acessar uma pasta.'}</p></section></div>`);$('.modal').classList.add('launcher-modal');$('#recent-project-query').oninput=e=>{const query=AmagoSearch.normalize(e.target.value);document.querySelectorAll('.recent-project-row').forEach(row=>row.hidden=!AmagoSearch.normalize(row.textContent).includes(query))}}
async function openLauncher(){await loadRecentProjects();showLauncher()}
workActions.switch=openLauncher;actions['workspaces']=openLauncher;commandList.unshift(['Escolher espaço ou projeto recente','workspaces','']);
const openWorkspaceBefore=openProject;
openProject=async function(id){if(openingProject)return;openingProject=true;launcherError='';const before=workbench.project;try{await openWorkspaceBefore(id);if(before!==workbench.project){clearProjectImages();studio.panes=[];studio.active=0;studio.files.clear();state.view='project-home';state.tag=null;await loadRecentProjects();render();if(discovery.indexPromise)discovery.indexPromise.then(()=>{if(state.view==='project-home')renderMain()})}else if($('#recent-project-list')){launcherError='A pasta não foi aberta. Verifique o acesso ou selecione-a com Abrir pasta.';$('.launcher-error').textContent=launcherError}}catch(error){toast(error.message);if($('.launcher-error'))$('.launcher-error').textContent=error.message}finally{openingProject=false}};
workActions.open=()=>openProject();actions['open-project']=workActions.open;
workActions.home=async()=>{if(!(await saveProjectFile()))return;state.view=workbench.source==='project'?'project-home':'home';state.tag=null;render()};
workActions.project=()=>{workbench.source='project';state.view='project-home';state.tag=null;closeModal();render()};
const navigationTree=renderTree;renderTree=function(){navigationTree();if(workbench.source==='project')$('.project-location')?.insertAdjacentHTML('afterend',`<button class="project-central-button ${state.view==='project-home'?'active':''}" data-workspace-action="home">${icon('home')}Central do projeto</button>`)};
function projectDashboard(){const all=projectFiles(),docs=discoveryDocs(),folders=flatten(workbench.project.entries).filter(e=>e.kind==='directory'),md=all.filter(e=>e.kind==='markdown'),images=all.filter(e=>e.kind==='image'),texts=all.filter(e=>e.kind==='text');const edges=new Set();for(const source of docs.filter(d=>d.kind==='markdown'))for(const link of AmagoSearch.metadata(source.body).links){const target=resolveLink(docs,source,link);if(target&&target.path!==source.path)edges.add([source.path,target.path].sort().join('|'))}const recent=[...all].sort((a,b)=>String(b.updated||'').localeCompare(String(a.updated||''))).slice(0,7),tags=AmagoEditing.tagPage(docs,'',0).items.slice(0,8);
 $('#crumb-workspace').textContent='Projeto';$('#crumb-folder').textContent=workbench.project.name+' / Central';$('#main').innerHTML=`<section class="observatory project-dashboard"><div class="orbit-top"><div><div class="orbit-label"><i></i>ÂMAGO / SEU PROJETO</div><h1>${esc(workbench.project.name)}</h1><p class="project-root-label">${esc(workbench.project.root)}</p></div><div class="orbit-actions"><button class="plain-button" data-workspace-action="switch">${icon('folder-open')}Trocar projeto</button><button class="solid-button" data-workspace-action="new-file">${icon('plus')}Nova nota</button></div></div><div class="orbit-metrics"><div class="metric"><small>DOCUMENTOS</small><strong>${md.length}</strong><p>notas Markdown · ${texts.length} textos</p></div><div class="metric"><small>PASTAS</small><strong>${folders.length}</strong><p>${all.length} arquivos no projeto</p></div><div class="metric"><small>CONEXÕES</small><strong>${edges.size}</strong><p>${discovery.indexing?'Indexando vínculos…':'Entre notas e arquivos locais'}</p></div><div class="metric"><small>IMAGENS</small><strong>${images.length}</strong><p>Prontas para visualizar</p></div></div><div class="orbit-columns"><section class="orbit-section"><h2>Arquivos recentes <small>Última modificação</small></h2>${recent.map(d=>`<button class="recent-note" data-project-file="${esc(d.path)}">${icon(fileLabel(d.kind))}<span><strong>${esc(d.name)}</strong><small>${esc(d.path)}</small></span><span>${d.updated?formatDate(d.updated):''} ↗</span></button>`).join('')||'<p>Esta pasta ainda não possui arquivos.</p>'}</section><div><section class="orbit-section"><h2>Pastas do projeto <small>${folders.length}</small></h2><div class="dashboard-folders">${folders.map(f=>`<button data-reveal-folder="${esc(f.path)}">${icon('folder')}<span>${esc(f.path)}</span><small>${flatten(f.children||[]).filter(e=>e.kind!=='directory').length}</small></button>`).join('')||'<p>Os arquivos estão na raiz do projeto.</p>'}</div></section><section class="orbit-section"><h2>Ideias conectadas</h2><div class="side-tags">${tags.map(([tag,count])=>`<button class="tag-chip" data-document-query="tag:&quot;${esc(tag)}&quot;"># ${esc(tag)} <small>${count}</small></button>`).join('')}</div><p>${searchSummary()}</p><button class="plain-button" data-open-universe>${icon('graph')}Explorar mapa do projeto</button></section></div></div></section>`;projectStats();$('#connection-count').textContent=edges.size+' conexões no projeto';
}

const navigationTabs=renderTabs;renderTabs=function(){if(workbench.source!=='project'){navigationTabs();return}$('#tabbar').innerHTML=workbench.tabs.map(path=>`<div class="tab project-tab ${workbench.file?.path===path&&state.view==='project'?'active':''}"><button class="project-tab-open" data-project-file="${esc(path)}">${icon(fileLabel(projectFiles().find(f=>f.path===path)?.kind||'file'))}<span>${esc(path.split('/').at(-1))}</span></button><button class="tab-close" data-close-project-tab="${esc(path)}" aria-label="Fechar ${esc(path.split('/').at(-1))}" title="Fechar aba — Ctrl W">${icon('close')}</button></div>`).join('')+'<button class="tab-add" data-workspace-action="new-file" aria-label="Novo arquivo Markdown">'+icon('plus')+'</button>'};
async function closeProjectTab(path){if(!(await saveProjectFile()))return;const index=workbench.tabs.indexOf(path),active=workbench.file?.path===path;workbench.tabs=workbench.tabs.filter(p=>p!==path);studio.panes=studio.panes.filter(p=>p.source!=='project'||p.id!==path);studio.active=Math.max(0,Math.min(studio.active,studio.panes.length-1));studio.files.delete(path);if(active){if(workbench.file?.url?.startsWith('blob:'))URL.revokeObjectURL(workbench.file.url);workbench.file=null;const next=studio.panes[studio.active]?.id||workbench.tabs[Math.min(index,workbench.tabs.length-1)];state.view='project-home';if(next){const cached=studio.files.get(next);if(cached){workbench.file=cached;state.view='project';render()}else{render();await openProjectFile(next)}return}}render()}

function closePersonalTab(id){persist();state.tabs=state.tabs.filter(tab=>tab!==id);studio.panes=studio.panes.filter(p=>p.source!=='vault'||p.id!==id);studio.active=Math.max(0,Math.min(studio.active,studio.panes.length-1));if(state.id===id){const next=studio.panes[studio.active]?.id||state.tabs.at(-1);if(next){openNote(next);return}state.view='home';state.tag=null}render()}
function connectionPanel(source,docs,project){const options={root:project?workbench.project?.root:'',aliases:d=>AmagoSearch.metadata(d.body).aliases},data=AmagoLinks.connections(docs,source,AmagoSearch.metadata,options),refs=AmagoLinks.references(source.body).filter(r=>AmagoLinks.local(r.target)),missing=data.missing.filter(link=>refs.some(r=>r.target===link||AmagoLinks.targetParts(r.target).path===link));const list=items=>items.map(d=>`<button class="backlink" ${project?`data-project-file="${esc(d.path)}"`:`data-note="${esc(d.id)}"`}>${icon(fileLabel(d.kind||'markdown'))}<span>${esc(d.title||d.name)}<small>${esc(d.path||d.folder||'')}</small></span></button>`).join('')||`<p class="empty-small">${discovery.indexing&&project?'Lendo vínculos do projeto…':'Nenhuma conexão encontrada.'}</p>`;return `<aside class="context-panel studio-project-context"><h3 class="context-title">${icon('graph')}Conexões da nota</h3><section class="panel-section"><h3 class="context-title">Links nesta nota <span class="count">${data.outgoing.length}</span></h3>${list(data.outgoing)}</section><section class="panel-section"><h3 class="context-title">Links para esta nota <span class="count">${data.incoming.length}</span></h3>${list(data.incoming)}</section>${missing.length?`<details class="panel-section missing-links"><summary>${missing.length} destino(s) não encontrado(s)</summary><p>Confira o caminho e a extensão. Em nomes repetidos, inclua a pasta.</p>${missing.map(link=>`<code>${esc(link)}</code>`).join('')}</details>`:''}<button class="plain-button" data-open-universe>Abrir mapa ${project?'do projeto':'do espaço'}</button></aside>`}
projectNoteContext=()=>connectionPanel(workbench.file,discoveryDocs(),true);
renderContext=n=>connectionPanel(n,vault.notes,false);
links=n=>AmagoSearch.metadata(n?.body).links;
findTitle=title=>resolveLink(vault.notes,{},title);

fileMarkdown=function(body,source=workbench.file){const refs=AmagoLinks.references(body).filter(r=>AmagoLinks.local(r.target)),replacements=[];let cursor=0,text='';for(const ref of refs){text+=body.slice(cursor,ref.start);const key='AMAGOLINK'+replacements.length+'X'+Math.random().toString(36).slice(2)+'END';text+=key;cursor=ref.end;const target=resolveLink(discoveryDocs(),source,ref.target),image=ref.embed&&target?.kind==='image';replacements.push([key,`<button class="wiki-link local-file-link ${image?'embedded-image':''} ${target?'':'unresolved-link'}" data-local-link="${esc(ref.target)}" data-link-source="${esc(source?.path||'')}" ${image?`data-linked-image="${esc(target.path)}"`:''} title="${esc(target?.path||ref.target)}">${image?'<span>Carregando imagem…</span>':esc(ref.label)}</button>`])}text+=body.slice(cursor);text=text.replace(/^ {0,3}\[[^\]\n]+\]:[^\n]*$/gm,'');let html=markdown(text,false);for(const [key,value] of replacements)html=html.replaceAll(key,value);return html};
async function hydrateLinkedImages(){const root=workbench.project?.root;for(const element of document.querySelectorAll('[data-linked-image]:not([data-image-requested])')){element.dataset.imageRequested='true';const path=element.dataset.linkedImage,key=root+'\0'+path;let entry=projectImages.get(key);if(!entry){entry={};entry.promise=window.projectAdapter.image(path).then(result=>{Object.assign(entry,result);return result});projectImages.set(key,entry)}try{const result=await entry.promise;if(!element.isConnected||root!==workbench.project?.root){if(result.url?.startsWith('blob:')&&!projectImages.has(key))URL.revokeObjectURL(result.url);continue}if(result.error){element.textContent='Não foi possível exibir '+path;continue}const img=document.createElement('img');img.src=result.url;img.alt=path;img.loading='lazy';element.replaceChildren(img)}catch{element.textContent='Imagem indisponível: '+path}}}
async function followLocalLink(element){const source=discoveryDocs().find(d=>d.path===element.dataset.linkSource)||workbench.file,target=resolveLink(discoveryDocs(),source,element.dataset.localLink);if(!target){toast('Destino não encontrado. Confira a pasta, a extensão e nomes repetidos.');return}await openProjectFile(target.path);const fragment=AmagoLinks.targetParts(element.dataset.localLink).fragment;if(fragment){const query=AmagoSearch.normalize(fragment.replace(/^\^/,''));const headings=[...document.querySelectorAll('.project-preview h1,.project-preview h2,.project-preview h3,.project-preview h4,.pane-preview h1,.pane-preview h2,.pane-preview h3')];headings.find(h=>AmagoSearch.normalize(h.textContent)===query)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}}

function addResizeHandle(parent,kind,index=0){if(parent.querySelector(`:scope>[data-resize="${kind}"]${kind==='columns'?`[data-resize-index="${index}"]`:''}`))return;const handle=document.createElement('button');handle.className='pane-resizer resize-'+kind;handle.dataset.resize=kind;handle.dataset.resizeIndex=index;handle.setAttribute('role','separator');handle.setAttribute('aria-orientation','vertical');handle.setAttribute('aria-label',kind==='context'?'Redimensionar painel de conexões':kind==='columns'?'Redimensionar colunas de notas':'Redimensionar editor e prévia');handle.title='Arraste para redimensionar · setas para ajustar · duplo clique para restaurar';handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();const rect=parent.getBoundingClientRect();if(kind==='columns'){rect.pairWidth=rect.width+(parent.nextElementSibling?.getBoundingClientRect().width||0);const weights=columnWeights();rect.pairWeight=weights[index]+weights[index+1]}handle.setPointerCapture(e.pointerId);document.body.classList.add('resizing-panes');const update=event=>resizeTo(handle,parent,rect,event.clientX);handle.onpointermove=update;handle.onpointerup=()=>{handle.onpointermove=null;document.body.classList.remove('resizing-panes');persist()};handle.onpointercancel=handle.onpointerup};handle.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const current=kind==='context'?interfacePrefs().contextWidth||285:kind==='columns'?50:interfacePrefs().editorRatio||50;const value=e.key==='Home'?(kind==='context'?210:20):e.key==='End'?(kind==='context'?620:80):current+(e.key==='ArrowRight'?1:-1)*(kind==='context'?12:2);if(kind==='context')interfacePrefs().contextWidth=Math.max(210,Math.min(620,value));else if(kind==='columns'){const weights=columnWeights(),total=weights[index]+weights[index+1],currentRatio=weights[index]/total,ratio=Math.max(.2,Math.min(.8,e.key==='Home'?.2:e.key==='End'?.8:currentRatio+(e.key==='ArrowRight'?.02:-.02)));weights[index]=total*ratio;weights[index+1]=total*(1-ratio);interfacePrefs().columnWeights=weights}else interfacePrefs().editorRatio=Math.max(20,Math.min(80,value));applyResizeLayout();persist()};handle.ondblclick=()=>{if(kind==='context')interfacePrefs().contextWidth=285;else if(kind==='columns')interfacePrefs().columnWeights=[1,1,1,1];else interfacePrefs().editorRatio=50;applyResizeLayout();persist()};kind==='context'?parent.prepend(handle):parent.append(handle)}
function columnWeights(){return [0,1,2,3].map(i=>Math.max(.3,Math.min(3,Number(interfacePrefs().columnWeights?.[i])||1)))}
function resizeTo(handle,parent,rect,x){const p=interfacePrefs(),kind=handle.dataset.resize;if(kind==='context')p.contextWidth=Math.max(210,Math.min(620,rect.right-x,innerWidth*.55));else if(kind==='editor')p.editorRatio=Math.max(20,Math.min(80,(x-rect.left)/rect.width*100));else{const weights=columnWeights(),index=+handle.dataset.resizeIndex;if(!parent.nextElementSibling)return;const both=rect.pairWidth,total=rect.pairWeight,ratio=Math.max(.2,Math.min(.8,(x-rect.left)/both));weights[index]=total*ratio;weights[index+1]=total*(1-ratio);p.columnWeights=weights}applyResizeLayout()}
function applyResizeLayout(){const p=interfacePrefs();document.body.style.setProperty('--context-width',(Math.max(210,Math.min(620,Number(p.contextWidth)||285)))+'px');document.body.style.setProperty('--editor-ratio',(Math.max(20,Math.min(80,Number(p.editorRatio)||50)))+'%');document.querySelectorAll('.editing-columns').forEach(grid=>{grid.style.gridTemplateColumns=studio.panes.map((_,i)=>`minmax(230px,${columnWeights()[i]}fr)`).join(' ')});document.querySelectorAll('[data-resize]').forEach(h=>{const context=h.dataset.resize==='context',weights=columnWeights(),i=+h.dataset.resizeIndex,value=context?p.contextWidth||285:h.dataset.resize==='columns'?100*weights[i]/(weights[i]+weights[i+1]):p.editorRatio||50;h.setAttribute('aria-valuemin',context?'210':'20');h.setAttribute('aria-valuemax',context?'620':'80');h.setAttribute('aria-valuenow',String(Math.round(value)))})}
function enhanceLayout(){document.querySelectorAll('#main>.context-panel').forEach(p=>addResizeHandle(p,'context'));document.querySelectorAll('.project-editor-grid.split,.split-content').forEach(p=>addResizeHandle(p,'editor'));document.querySelectorAll('.editing-pane').forEach((p,i)=>{if(i<studio.panes.length-1)addResizeHandle(p,'columns',i)});applyResizeLayout();hydrateLinkedImages();pinModalActions()}
function pinModalActions(){const modal=$('.modal');if(!modal)return;for(const actionsBar of modal.querySelectorAll('.modal-body .modal-actions')){const form=actionsBar.closest('form');if(!form)continue;if(!form.id)form.id='modal-form-'+Date.now();for(const button of actionsBar.querySelectorAll('button'))if(!button.hasAttribute('type')||button.type==='submit')button.setAttribute('form',form.id);actionsBar.classList.add('modal-pinned-actions');modal.append(actionsBar)}}
let layoutFrame;const layoutObserver=new MutationObserver(()=>{cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(enhanceLayout)});layoutObserver.observe($('#main'),{childList:true,subtree:true});layoutObserver.observe($('#modal-root'),{childList:true,subtree:true});
const navigationMain=renderMain;renderMain=function(){if(workbench.source==='project'&&state.view==='project-home'){projectDashboard();updateStudioTools();applyInterface()}else navigationMain();enhanceLayout()};
const navigationRefresh=refreshSearchResults;refreshSearchResults=function(){navigationRefresh();if(state.view==='project-home'&&workbench.source==='project'&&!discovery.indexing)projectDashboard()};
document.addEventListener('input',e=>{if(!e.target.matches('#editor,[data-pane-editor],#project-editor'))return;clearTimeout(connectionRefreshTimer);connectionRefreshTimer=setTimeout(()=>{const panel=$('#main>.context-panel');if(!panel)return;panel.outerHTML=workbench.source==='project'?projectNoteContext():renderContext(note());updateStudioTools()},350)});let connectionRefreshTimer;
document.addEventListener('click',async e=>{const element=e.target.closest('[data-recent-project],[data-forget-project],[data-launch-vault],[data-close-project-tab],[data-close-tab],[data-local-link],[data-reveal-folder]');if(!element)return;e.preventDefault();e.stopImmediatePropagation();try{if(element.dataset.recentProject)await openProject(element.dataset.recentProject);if(element.dataset.forgetProject){const result=await window.projectAdapter.forget(element.dataset.forgetProject);if(result.error)throw Error(result.error);await loadRecentProjects();showLauncher()}if(element.hasAttribute('data-launch-vault')){launcherError='';await workActions.vault()}if(element.dataset.closeProjectTab)await closeProjectTab(element.dataset.closeProjectTab);if(element.dataset.closeTab)closePersonalTab(element.dataset.closeTab);if(element.dataset.localLink!==undefined)await followLocalLink(element);if(element.dataset.revealFolder){const path=element.dataset.revealFolder,parts=path.split('/');parts.forEach((_,i)=>workbench.expanded.add(parts.slice(0,i+1).join('/')));workbench.tab='explore';renderTree();const row=[...document.querySelectorAll('[data-project-dir]')].find(el=>el.dataset.projectDir===path);row?.scrollIntoView({block:'center'});row?.focus()}}catch(error){toast(error.message)}},true);
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='w'&&!$('.modal')){e.preventDefault();e.stopImmediatePropagation();if(workbench.source==='project'&&workbench.file)closeProjectTab(workbench.file.path).catch(error=>toast(error.message));else if(workbench.source==='vault'){closePersonalTab(state.id)}}},true);
// Show the splash immediately, then the selector after persisted data is ready.
let startupDone=false;const startedAt=performance.now();async function finishStartup(){if(startupDone)return;startupDone=true;const enabled=interfacePrefs().splashEnabled!==false;window.amagoStartup.setEnabled(enabled);if(!enabled)$('#startup-splash')?.remove();await loadRecentProjects();if(!enabled){showLauncher();return}const remaining=matchMedia('(prefers-reduced-motion: reduce)').matches?0:Math.max(0,950-(performance.now()-startedAt));setTimeout(()=>{const splash=$('#startup-splash');splash?.classList.add('splash-complete');showLauncher();setTimeout(()=>splash?.remove(),300)},remaining)}
window.addEventListener('amago-ready',finishStartup);if(window.amagoReady)finishStartup();setTimeout(()=>{if(!startupDone){launcherError='A inicialização levou mais tempo que o esperado. Confira o armazenamento antes de editar.';finishStartup()}},10000);
render();
